                'filename': 'foo.pdf',
                'hashes': {
                    'md5': '0123456789ABCDEF',
                    'sha1': '0123456789ABCDEF0123456789ABCDEF01234567',
                    'sha256': (
                        '0123456789ABCDEF0123456789ABCDEF01234567'
                        + '0123456789ABCDEF0123456789ABCDEF01234567'
                    )
                },
                'info': {'ext': 'pdf'}
            }
        )
        == {
            'File': {
                'Name': 'foo.pdf',
                'MD5': '0123456789ABCDEF',
                'SHA1': '0123456789ABCDEF0123456789ABCDEF01234567',
                'SHA256': (
                    '0123456789ABCDEF0123456789ABCDEF01234567'
                    + '0123456789ABCDEF0123456789ABCDEF01234567'
